create function public.register_app_user(p_user_id uuid,p_username text,p_password_hash text,p_favorites jsonb,p_trips jsonb,p_preferences jsonb) returns void language plpgsql security invoker set search_path='' as $$
begin insert into public.app_users(id,username,password_hash) values(p_user_id,p_username,p_password_hash); insert into public.user_states(user_id,favorites,trips,preferences) values(p_user_id,p_favorites,p_trips,p_preferences); insert into public.user_usage_events(user_id,event_type) values(p_user_id,'register'); end; $$;
create function public.record_app_login(p_user_id uuid) returns void language plpgsql security invoker set search_path='' as $$ begin update public.app_users set last_login_at=now(),updated_at=now() where id=p_user_id; insert into public.user_usage_events(user_id,event_type) values(p_user_id,'login_success'); end; $$;
create function public.save_app_user_state(p_user_id uuid,p_favorites jsonb,p_trips jsonb,p_preferences jsonb) returns timestamptz language plpgsql security invoker set search_path='' as $$ declare saved_at timestamptz:=now(); begin insert into public.user_states(user_id,favorites,trips,preferences,updated_at) values(p_user_id,p_favorites,p_trips,p_preferences,saved_at) on conflict(user_id) do update set favorites=excluded.favorites,trips=excluded.trips,preferences=excluded.preferences,updated_at=saved_at; insert into public.user_usage_events(user_id,event_type) values(p_user_id,'state_sync'); return saved_at; end; $$;
revoke all on function public.register_app_user(uuid,text,text,jsonb,jsonb,jsonb) from public,anon,authenticated; revoke all on function public.record_app_login(uuid) from public,anon,authenticated; revoke all on function public.save_app_user_state(uuid,jsonb,jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.register_app_user(uuid,text,text,jsonb,jsonb,jsonb) to service_role; grant execute on function public.record_app_login(uuid) to service_role; grant execute on function public.save_app_user_state(uuid,jsonb,jsonb,jsonb) to service_role;
